INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (2, "---", 1, 1, 1, 0, 1, "", "", "アヤネ");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (1, "---", 1, 3, 2, 6000, 0, "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", "", "アサヒ");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (3, "アドレナリン", 1, 0, 3, 16000, 3, "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", "ホームランを連発すると、連発数に応じてパワーアップする", "部員3");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (2, "ラッキー", 1, 2, 4, 30000, 2, "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", "幸運のハプニングを呼び込む", "{0}");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (0, "", 0, 1, 5, 50000, 1, "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", "", "選手名鑑 おまけページ");
INSERT INTO `v1_6b3fa644007545688bb7d1d141ddfa4755d9f3b1867491d347e7f1b54871c8cf` VALUES (1, "", 0, 1, 6, 50000, 0, "", "", "選手名鑑 おまけページ");
